    mahjong_new_game: "新しいゲーム",
    mahjong_shuffle: "残りの牌をシャッフル",
    chess_history_intro: "古代インドの戦争ゲームから、世界で最も研究されているボードゲームへ。チェスは大陸と時代を越えて、今の姿になりました。",
    go_history_intro: "囲碁は、今も生まれた当時とほぼ同じ形で遊ばれ続けている最古のボードゲームの一つです。石と陣地をめぐるこのゲームの起源は、おそらく中国で2,500年以上前にさかのぼります。",
    checkers_history_intro: "チェッカー（ドラフツ）は、シンプルなルールと奥深い戦略を持つゲームで、古くからある盤と、新しい駒の取り方を組み合わせることで生まれました。",
    ur_history_intro: "およそ4,600年前に生まれたウルの王家のゲームは、これまでに発見された中で最も古いボードゲームの一つです。そして2000年にもわたる推理の末に、今もオリジナルのルールで遊べる数少ない古代のゲームの一つでもあります。",
    morris_history_intro: "エジプトの神殿の屋根から、イギリスの大聖堂の回廊まで、これほど多くの時代を通じてこれほど多様な場所に刻まれてきたゲームは、そう多くありません。",
    backgammon_history_intro: "バックギャモンの系譜は、サイコロを振ってきたほぼすべての文明を貫いています。古代メソポタミアやローマから、現代中東のコーヒーハウスに至るまで。",
    xiangqi_history_intro: "中国将棋（シャンチー）は国際チェスと深いルーツを共有しながらも、1,000年以上をかけて独自の道を歩み、今日では何億人もの人々に遊ばれるゲームになりました。",
    mancala_history_intro: "マンカラは単一のゲームではなく、ゲームの一族全体を指す言葉です。地球上で最も古いゲームファミリーの一つで、種や石を穴の間で移動させるというシンプルで普遍的な動作を中心に成り立っています。",
    reversi_history_intro: "ヴィクトリア朝のサロンゲームが、1世紀の時を隔てて2度も生まれ変わった物語です。",
    fourinarow_history_intro: "重力を利用したシンプルなアイデアが、20世紀を代表するベストセラーゲームの一つへと育っていった物語です。",
    gomoku_history_intro: "単純に並べるだけのゲームでありながら、そのシンプルさゆえに競技プレイヤーたちがルールの変更を迫られることになった物語です。",
    tictactoe_history_intro: "おそらく最もよく知られた紙と鉛筆のゲーム。そのルーツは古代ローマにあり、コンピューターの歴史にも名を残しています。",
    senet_history_intro: "これまでに発見された中で最も古いボードゲームの一つでありながら、その正確なルールが何千年もの間失われたままになっているゲームです。",
    shogi_history_intro: "チェス一族の中で日本独自に発展した将棋は、取った駒がゲームから去るのではなく、取った側の戦力に加わるという珍しい特徴を持つ唯一の主要なバリエーションです。",
    sudoku_history_intro: "このコレクションの他のどのゲームとも違い、数独にはまったく古代の系譜がありません。パーソナルコンピューターとほとんど変わらないほど新しいゲームです。",
    pegsolitaire_history_intro: "宮廷の伝説を持つほど古い一人用パズルであり、レクリエーション数学における意外な結果の一つの題材でもあります。",
    minesweeper_history_intro: "「最初の一手は絶対に安全」という、このゲームを特徴づけるルールは、印刷されたページではなくコンピューターがその場で盤を生成できるようになって初めて標準になったものです。",
    nonogram_history_intro: "世界の反対側で、ほぼ同じ時期に、それぞれ独立して発明された論理パズルです。名前は、その2人の発明者の一人にちなんでいます。",
    twenty48_history_intro: "ほとんどが他のゲームのアイデアの組み合わせから成り、たった週末だけで作られたにもかかわらず、それ以前のどのブラウザゲームよりも多くの人にクローンされたゲームです。",
    mahjong_history_intro: "まったく別の4人用ゲームから名前と見た目を借りているものの、それ以外にはほとんど共通点のない、1人用の牌合わせゲームです。",
