    release_v223: "オフライン用の保存がより確実になり、ゲームが系統ごとにまとめられ、ドミノに「三角形」のバリエーションが、「ケーキを取ったのはだれ?」に「ネコと魚」のテーマと追加のヒントが加わりました。",
    release_v224: "カード対決：同じ強さの4つのデッキで、コンピューターとも、1台で2人でも遊べます。",
    release_v225: "おとぎ話の悪役：グリム童話の6人の悪役がそれぞれの目的を目指します。2〜4人用。",
    release_v226: "森の村：森の動物たちが季節をめぐって村を作ります。1〜4人用。",
    release_v227: "冒険ブック：ひとり用ロールプレイングゲーム。主人公を作って洞窟・塔・森を探検しよう。",
    release_v228: "ホームページ下部の小さなリンクから、制作中の新しいプロジェクトQuillwildへ行けます。",
    release_v229: "ホームページが短くなり、カテゴリーごとのページができました。",
    release_v230: "カード対決：すべてのカードに絵がつきました。",
    release_v234: "タングラムに、新しい図形29個の新レベル「輪郭だけ」が加わりました。",
    release_v235: "「絵さがし」に9つの部屋と40以上の新しい絵が加わりました。「ケーキを取ったのはだれ?」には家族のテーマと、子どもと宝物のテーマが加わりました。",
    release_v236: "「絵さがし」に浴室、地下室、寝室が加わりました。「ケーキを取ったのはだれ?」には部屋が5つ、家具が7つ増えました。",
