    home_pairs_desc: "カードを2枚めくってペアを見つけよう：シンプルな白黒の図形、動物、果物と野菜、乗り物を使った定番のカード合わせゲーム。1人で手数に挑戦、1台の端末で2人プレイ、または内蔵エンジンと対戦。",
