    freecell_history_intro: "その中で最も有名なバリエーションが、1990年代の特定のソフトウェアのおかげで有名になったという、めずらしい経緯を持つ、100年の歴史を持つカードゲームの一族です。",
    game_lightswitch: "ライトスイッチ",
    home_lightswitch_desc: "セルをタップすると、そのセルと隣接するセルのオン・オフが切り替わります。すべてのライトを消せばクリアです。パズルは必ず解けるように生成されます。",
