    about_trademarks: "歴史のページでは、遊び方の由来を客観的に説明するために、市販のゲームの名前に触れています。これらの名前の一部は、それぞれの権利者の登録商標です。PaperGamesはこれらの権利者と関係がなく、支援、後援、審査も受けていません。ここにあるゲームはすべて独自に作られたもので、市販版の素材は一切使っていません。",
