    nikoli_trademark_notice: "数独、カックロ、スリザーリンクという名前は日本における出版社ニコリの登録商標であり、橋をかけろはニコリがこのパズルを発表している名前です。PaperGamesはニコリと関係がなく、ニコリの支援や審査も受けていないため、日本語版では別の名前を使っています。パズルの種類そのものは自由に使えるもので、ここにあるパズルはすべて端末上で新しく作られています。",

