    home_blockers_desc: "2〜4人で盤の上にあるゴールを目指すサイコロレース。石が道をふさぎ、石に止まった人はそれをほかの人の行く手に置けます。コンピューター相手でも、1台の端末で友だちとでも遊べます。",
    bl_level_label: "レベル",
    bl_board_aria: "通せんぼ石の盤",
    bl_history_intro: "通せんぼ石はPaperGamesオリジナルのレースゲームで、コマを家に戻す、道をふさぐといったサイコロレースゲームの古い要素を取り入れています。",
