    home_villains_desc: "各プレイヤーはグリム童話の悪役になり、それぞれの目的を目指します。魔女、オオカミ、ルンペルシュティルツヒェンなど。ほかのプレイヤーは英雄を送り込んで邪魔します。2〜4人、コンピューター対戦または1台で遊べます。",
    quickrules_villains_1: "自分の悪役の目的をいちばん先に達成しよう。目的カードに、あと何が足りないかが表示されます。",
