    ab_room_cave_1: "天井から小さな澄んだ水たまりに水がしたたっている。",
    ab_room_cave_2: "青い水晶が壁から生え、やさしく光っている。",
    ab_room_cave_3: "せまい通路。低い岩の下をかがんで進む。",
    ab_room_cave_4: "さびたレールの上に古いトロッコが止まっている。昔だれかがここで働いていた。",
    ab_room_cave_5: "洞窟が高い広間に開けている。足音がひびく。",
    ab_room_cave_6: "きらきらした砂が床をおおい、ブーツの下でざくざく鳴る。",
    ab_room_cave_7: "岩のすきまから冷たい風が吹いてくる。",
    ab_room_cave_8: "いすほどもある大きなキノコが生えている。土のにおいがする。",
    ab_room_cave_9: "地下の小川が石のみぞをさらさら流れている。",
    ab_room_cave_10: "壁の一面に、ふしぎな星の絵が描かれている。",
    ab_room_cave_11: "つらら石が石のつららのように天井から下がっている。",
    ab_room_cave_12: "小さなわき穴。だれかが古い毛布を置いていった。",
    ab_room_cave_13: "道はコケですべりやすい、なめらかな岩の上を登っていく。",
    ab_room_cave_14: "暗いすみでコウモリが眠っている。つま先立ちで進む。",
    ab_room_cave_15: "みがいたようになめらかな床の、丸い部屋。",
    ab_room_cave_16: "緑のコケが壁をうす明るく照らしている。",
    ab_room_cave_17: "昔はここにつり橋がかかっていた。今は柱だけが残っている。",
    ab_room_cave_18: "ここは空気があたたかい。どこか深い下のほうで何かがごろごろ鳴る。",
    ab_room_cave_19: "大きな石がはじけたように、水晶のかけらがあちこちに散らばっている。",
    ab_room_cave_20: "静かなすみっこ。ランプが長いかげを落とす。",
    ab_room_tower_1: "ほこりをかぶった本がぎっしりの棚が天井まで届いている。",
    ab_room_tower_2: "らせん階段が上へと続いている。段がぎしぎし鳴る。",
    ab_room_tower_3: "はりにとまったカラスたちが、光る目でこちらを見ている。",
    ab_room_tower_4: "古い台所。冷えたかまどの上になべがつるしてある。",
    ab_room_tower_5: "丸い窓から、はるか下の森が見える。",
    ab_room_tower_6: "大きな机のある書斎。つぼのインクはかわいている。",
    ab_room_tower_7: "ガラスのかべの向こうで、歯車がゆっくり回っている。チク、タク。",
    ab_room_tower_8: "肖像画がならぶ長い廊下。絵の目がこちらを追ってくるようだ。",
    ab_room_tower_9: "地図だらけの部屋。そのひとつに、この塔のような塔が描かれている。",
    ab_room_tower_10: "だれもいないようなのに、テーブルの上でろうそくが燃えている。",
    ab_room_tower_11: "乾いたハーブや色とりどりの粉のびんがならぶ物置。",
    ab_room_tower_12: "こわれたよろい戸から風がひゅうひゅう吹きこむ。",
    ab_room_tower_13: "音楽の部屋。ハープがひとりでに音をひとつ鳴らす。",
    ab_room_tower_14: "板でできた細い橋が、かべからかべへかかっている。",
    ab_room_tower_15: "天がい付きベッドのある寝室。カーテンは穴だらけ。",
    ab_room_tower_16: "空に向けた望遠鏡のある仕事部屋。",
    ab_room_tower_17: "黒い羽が床じゅうに落ちている。",
    ab_room_tower_18: "かべに鏡がかかっているが、映っているのは別の部屋だ。",
    ab_room_tower_19: "小さなバルコニー。ここでは風が雨のにおいがする。",
    ab_room_tower_20: "黒と白のタイルがしかれた、ひんやりした広間。",
    ab_room_forest_1: "木々のあいだに霧がたちこめ、自分の手もほとんど見えない。",
    ab_room_forest_2: "花いっぱいの草地。日なたでミツバチがぶんぶん飛んでいる。",
    ab_room_forest_3: "シダにおおわれた古い小道。",
    ab_room_forest_4: "中に立てるほど大きな、うろのある木。",
    ab_room_forest_5: "小さな池。近づくとカエルが水に飛びこむ。",
    ab_room_forest_6: "うでほどの太さの根が道を横切っている。",
    ab_room_forest_7: "高いこずえで鳥が歌っている。",
    ab_room_forest_8: "草の中に白い石が輪になって置かれている。",
    ab_room_forest_9: "石がきに沿ってブラックベリーのしげみが生えている。",
    ab_room_forest_10: "地面はコケでやわらかく緑色。とても静かだ。",
    ab_room_forest_11: "たおれた木の幹が、橋のようにくぼ地にかかっている。",
    ab_room_forest_12: "見すてられた小屋。戸が開いたままになっている。",
    ab_room_forest_13: "背の高いマツが風にきしむ。",
    ab_room_forest_14: "しめ地の上で小さな光がおどっている。",
    ab_room_forest_15: "樹皮に顔がほられた、巨大なカシの木。",
    ab_room_forest_16: "キノコがきれいな輪になって生えている。",
    ab_room_forest_17: "小川がなめらかな小石の上をさらさら流れる。",
    ab_room_forest_18: "暗いやぶ。枝がそでをひっかく。",
    ab_room_forest_19: "日当たりのよい丘。ここから見ると、下の霧が海のようだ。",
    ab_room_forest_20: "古い石段が二本のシラカバのあいだに続いている。",
    home_adventurebook_desc: "ひとりで遊ぶロールプレイングゲーム。主人公を作り、洞窟・塔・森を一部屋ずつ探検し、判定や戦いでサイコロをふって、なくした宝を持ち帰ろう。かんたん・ふつう・むずかしい。",
    quickrules_adventurebook_1: "主人公を作り、その場所の宝を見つけて入口まで持ち帰ろう。",
    quickrules_adventurebook_2: "判定：サイコロ2個と能力値の合計が、示された数に届けば成功。結果は計算つきで表示される。",
    quickrules_adventurebook_3: "戦いはラウンド制：攻撃・防御・道具・クラスの技・逃げる。ゲームは一歩ごとに保存される。",
