    home_differences_desc: "3か所、5か所、7か所ちがう2枚の絵:なくなっている、模様がちがう、左右が反対、位置がずれている。どちらの絵でも、ちがうところをタップします。時間制限なし、困ったらヒントもあります。「絵さがし」では、台所、屋根裏、庭など12の部屋の大きな絵の中から5〜10のものをさがします。",
    df_history_intro: "新聞や子ども向け雑誌、パズル本でおなじみのパズルです。いつどこで最初に登場したのかは、確かな記録がありません。",
