    home_pentomino_desc: "5つの正方形でできた12個のピースを長方形にしきつめます。回転と裏返しはタップで、ドラッグは不要です。4つの大きさで自由に置くか、最初からいくつかのピースが置かれた答えが1つだけの問題で遊べます。",
    pt_history_intro: "5つの正方形でできた12個のピース。ヘンリー・デュードニーが1907年にパズルとして発表し、1953年にソロモン・ゴロムが「ペントミノ」と名づけました。",
