    game_arrows: "矢印パズル",
    home_arrows_desc: "矢印をタップすると、ほかの矢印がじゃまでなければ盤の外へすべり出ます。盤をすべて空にしましょう。どの問題も解くことができ、取り消しとヒントがあり、時間制限はありません。「むずかしい」と「マスター」では、ふさがれた矢印が前に滑り、動けなくなることがあります。",
    aw_history_intro: "一方向にしか動けないコマは、1880年に大流行したスライドパズルの仲間です。矢印を使う形は新しいパズルです。",
    quickrules_arrows_1: "矢印をタップすると、端までの道があいていれば、その向きに盤の外へ出ます。",
    quickrules_arrows_2: "ほかの矢印がじゃまなときは何も起きません。先にそちらを外に出しましょう。「むずかしい」と「マスター」では、その矢印の手前まで滑ります。",
    quickrules_arrows_3: "盤をすべて空にしましょう。どの問題も解けます。「ヒント」は外に出られる矢印に印を付けます。",
