    game_loosen: "リングほどき",
    home_loosen_desc: "互いにからんだリングには、それぞれすき間があります。回すと、からんだリングは逆向きに回ります。1つずつ外れるまで回しましょう。3つのレベル、最少手数、元に戻す、ヒント付き。",
    lr_history_intro: "リングのパズルは古く、知恵の輪「チャイニーズ・リング」は1500年ごろには記録されています。すき間のある平らなこの形は新しいものです。",
    quickrules_loosen_1: "リングをタップすると時計回りに4分の1回転し、からんだリングは逆向きに回ります。",
