    game_catplaces: "ねこの居場所",
    home_catplaces_desc: "どの行・どの列・どの部屋にもねこをちょうど1匹ずつ。ねこ同士は角でも触れてはいけません。3つの大きさのロジックパズルで、どれも答えはひとつ、当て推量なしで解けます。",
    kz_history_intro: "ルールは2003年にオランダで開かれた世界パズル選手権のために考案されたロジックパズルから来ています。ここでは星の代わりに眠るねこを置きます。",
