    game_rings: "リング回し",
    home_rings_desc: "3〜5本のリングが重なり、図形がかかれています。真ん中から外へのびる各線に同じ図形がならぶまでリングを回しましょう。「むずかしい」ではリングがとなりのリングもいっしょに回します。最少手数の表示とヒントボタンがあります。",
    rg_history_intro: "記号のついた輪を回して合わせるしかけは古くからあります。レオン・バッティスタ・アルベルティは1467年に、回る2つの輪でできた暗号円盤を記しました。ここのパズルはPaperGamesのために作ったものです。",
    quickrules_rings_1: "絵の下のボタンで、リングを左 ↺ か右 ↻ に回します。",
    quickrules_rings_2: "目的:真ん中から外への8本の線のどれも、すべてのリングで同じ図形になること。",
