    game_matches: "マッチ棒パズル",
    home_matches_desc: "マッチ棒を1本か2本動かして、まちがった式を正しくするか、図形を指定された数の正方形にしましょう。3つのレベルに90問、どれもコンピューターでたしかめてあります。マッチ棒をタップしてからあいた場所をタップ。ドラッグは不要です。",
    mt_history_intro: "マッチは19世紀に身近なものになり、まもなくパズルの材料にもなりました。プロフェッサー・ホフマンの本『Puzzles Old and New』(1893年)には、すでにマッチ棒パズルの章があります。",
