    game_tangram: "タングラム",
    home_tangram_desc: "7つの定番のピース（三角形、正方形、平行四辺形）で輪郭を埋めましょう。4つのレベルに90の輪郭があり、どれもコンピューターで解を確認済みです。「輪郭だけ」では外側の線しか見えず、ピースはタップした所に置かれるので、試しながら解きます。ピースをタップし、回して、置く場所をタップ。ドラッグは不要です。",
    tg_history_intro: "正方形から切り分けた7つのピース。このパズルは中国生まれで、現存する最古の本は1813年に印刷されました。1817年からはヨーロッパで大流行しました。",
